async fn max_length_is_ok() {
    let cfg = ProcessConfig::default();
    let input = "a".repeat(MAX_INPUT_LENGTH);
    let out = process(&input, &cfg).await.unwrap();
    assert_eq!(out.original.len(), MAX_INPUT_LENGTH);
