async fn too_long_is_error() {
    let cfg = ProcessConfig::default();
    let input = "a".repeat(MAX_INPUT_LENGTH + 1);
    let err = process(&input, &cfg).await.unwrap_err();
    assert!(matches!(err, ProcessError::InputTooLong(n) if n == MAX_INPUT_LENGTH + 1));
}
```

### Unicode transformation + char_count

```rust
#[tokio::test]
async fn unicode_is_handled_and_char_count_is_correct() {
    let cfg = ProcessConfig::default();
    let input = "  HéLlÖ   世界  ";
    let out = process(input, &cfg).await.unwrap();

    // words => ["héllö", "世界"] => joined => "héllö 世界" => uppercase
    assert_eq!(out.transformed, "HÉLLÖ 世界");

    // char_count counts chars, not bytes
    assert_eq!(out.char_count, input.chars().count());
    assert_eq!(out.word_count, 2);
}
```

